mapper.select:
select  from mc_content

    and content_type = #{contentType}
    and title like concat('%', #{title}, '%')
    and status = #{status}

order by sort_order, content_id

mapper.update:
update mc_content set content_key=#{contentKey}, content_type=#{contentType}, title=#{title}, category=#{category}, summary=#{summary},
payload_json=#{payloadJson}, status=#{status}, sort_order=#{sortOrder}, update_by=#{updateBy}, update_time=sysdate()
where content_id=#{contentId}

mapper.select:
select  from mc_record

    and record_type = #{recordType}
    and client_id = #{clientId}
    and title like concat('%', #{title}, '%')
    and contact_phone like concat('%', #{contactPhone}, '%')
    and status = #{status}

order by update_time desc, record_id desc

select count(*) from mc_record
where client_id=#{clientId} and record_type=#{recordType} and content_key=#{contentKey}
  and record_key != #{recordKey} and status != 'canceled'

select count(*) from mc_record
where client_id=#{clientId} and record_type='consultation' and record_key != #{recordKey}
  and status != 'canceled'
  and json_unquote(json_extract(data_json, '$.date'))=#{appointmentDate}
  and json_unquote(json_extract(data_json, '$.time'))=#{appointmentTime}

select coalesce(sum(cast(json_unquote(json_extract(data_json, '$.count')) as unsigned)), 0)
from mc_record where record_type='activity' and content_key=#{contentKey}
  and client_id != #{clientId} and status != 'canceled'
